        return -1;
    }
    int lastDotIndex = filename.lastIndexOf('.');
    if (lastDotIndex == -1) {
        return -1;
    }
    int lastSeparatorIndex = filename.lastIndexOf(File.separatorChar);
    if (lastSeparatorIndex >= 0 && lastSeparatorIndex >= lastDotIndex) {
        return -1;
    }
    return lastDotIndex;
}

